Создание структуры для змейки:

```c
typedef struct {
    int x, y;
    int dir_x, dir_y;
    int length;
} Snake;

// Создание змейки с заданными координатами и длиной
Snake create_snake(int x, int y, int length) {
    Snake s = {x, y, 0, 0, length};
    return s;
}

// Обновление положения головы змейки
void update_snake_head(Snake* snake, int delta_x, int delta_y) {
    snake->x += delta_x;
    snake->y += delta_y;
    snake->dir_x = delta_x;
    snake->dir_y = delta_y;
}

// Добавление новой головы змейки
void add_snake_head(Snake* snake) {
    Snake new_head = {snake->x + snake->dir_x, snake->y + snake->dir_y, 0, 0, snake->length + 1};
    snake->length = new_head.length;
    memcpy(snake, &new_head, sizeof(Snake));
}

// Удаление хвоста змейки
void remove_snake_tail(Snake* snake) {
    snake->length--;
    Snake* tail = &snake[snake->length];
    tail->x = -1;
    tail->y = -1;
}
```

